<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const element = (tag, text, attributes = {}) => {
      const node = document.createElement(tag);
      if (text !== undefined) node.textContent = text;
      for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, value);
      return node;
    };

    async function render() {
      const match = location.pathname.match(/^\/projects\/(\d+)$/);
      if (match) {
        const projects = await fetch('/api/projects').then(response => response.json());
        const project = projects.find(item => String(item.id) === match[1]);
        app.replaceChildren();
        const back = element('button', 'Projects');
        back.addEventListener('click', () => { location.href = '/'; });
        app.append(back);
        if (project) {
          app.append(element('h1', project.name));
          if (project.archived) app.append(element('p', 'Archived project'));
          const form = element('form');
          const input = element('input', undefined, { type: 'text', 'aria-label': 'Task title', autocomplete: 'off' });
          const submit = element('button', 'Create task', { type: 'submit' });
          submit.disabled = project.archived;
          form.append(input, submit);
          const alert = element('p', undefined, { role: 'alert', hidden: '' });
          const filterLabel = element('label', 'Task filter');
          const filter = element('select', undefined, { 'aria-label': 'Task filter' });
          for (const value of ['All', 'Open', 'Completed']) filter.append(element('option', value, { value }));
          filterLabel.append(filter);
          const list = element('section', undefined, { 'aria-label': 'Tasks' });
          form.addEventListener('submit', async event => {
            event.preventDefault();
            const title = input.value.trim();
            if (!title) {
              alert.textContent = 'Task title is required';
              alert.hidden = false;
              input.focus();
              return;
            }
            const response = await fetch(`/api/projects/${project.id}/tasks`, {
              method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title })
            });
            if (response.ok) {
              input.value = '';
              alert.hidden = true;
              await loadTasks(project.id, list, filter.value);
            }
          });
          filter.addEventListener('change', () => loadTasks(project.id, list, filter.value, project.archived));
          app.append(form, alert, filterLabel, list);
          await loadTasks(project.id, list, filter.value, project.archived);
        } else app.append(element('h1', 'Project not found'));
        return;
      }

      app.replaceChildren(element('h1', 'Workboard'));
      const form = element('form');
      const input = element('input', undefined, { type: 'text', 'aria-label': 'Project name', autocomplete: 'off' });
      const submit = element('button', 'Create project', { type: 'submit' });
      form.append(input, submit);
      const alert = element('p', undefined, { role: 'alert', hidden: '' });
      const filterLabel = element('label', 'Project filter');
      const filterSelect = element('select', undefined, { 'aria-label': 'Project filter' });
      for (const value of ['Active', 'Archived']) filterSelect.append(element('option', value, { value }));
      filterLabel.append(filterSelect);
      const list = element('section', undefined, { 'aria-label': 'Projects' });
      form.addEventListener('submit', async event => {
        event.preventDefault();
        const name = input.value.trim();
        if (!name) {
          alert.textContent = 'Project name is required';
          alert.hidden = false;
          input.focus();
          return;
        }
        const response = await fetch('/api/projects', {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
        });
        if (response.ok) {
          input.value = '';
          alert.hidden = true;
          await loadProjects(list, filterSelect.value, filterSelect);
        }
      });
      filterSelect.addEventListener('change', () => loadProjects(list, filterSelect.value, filterSelect));
      app.append(form, alert, filterLabel, list);
      await loadProjects(list, filterSelect.value, filterSelect);
    }

    async function loadProjects(list, filter, filterSelect) {
      // Filter changes and archive actions can overlap. Ignore stale responses
      // so an older result cannot remove the row the user is interacting with.
      const requestId = String(Number(list.dataset.requestId || 0) + 1);
      list.dataset.requestId = requestId;
      const projects = await fetch('/api/projects').then(response => response.json());
      if (list.dataset.requestId !== requestId || !list.isConnected) return;
      const rows = new Map([...list.querySelectorAll('[data-project-id]')]
        .map(row => [row.dataset.projectId, row]));
      // Keep project rows mounted across filter changes and archive/restore
      // refreshes. This gives controls a stable DOM identity while requests
      // finish and lets the browser keep an in-progress interaction intact.
      for (const project of projects) {
        let row = rows.get(String(project.id));
        if (!row) {
          row = element('div', undefined, {
            'data-testid': 'project-row', 'data-project-id': project.id, class: 'project-row'
          });
          const name = element('span', undefined, { class: 'project-name' });
          const actions = element('span', undefined, { class: 'project-actions' });
          const summary = element('span', undefined, {
            'data-testid': 'project-summary', class: 'project-summary'
          });
          const open = element('button', 'Open project');
          open.addEventListener('click', () => { location.href = `/projects/${project.id}`; });
          const action = element('button', undefined, { class: 'secondary' });
          action.addEventListener('click', async () => {
            const archived = action.dataset.archived === 'true';
            // Keep the row stable while the archive request is in flight. A
            // second click here could otherwise race the list refresh and
            // make the row repeatedly disappear and return.
            action.disabled = true;
            try {
              const response = await fetch(`/api/projects/${project.id}/archive`, {
                method: 'PATCH', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ archived: !archived })
              });
              if (response.ok) await loadProjects(list, filterSelect.value, filterSelect);
            } finally {
              action.disabled = false;
            }
          });
          actions.append(summary, open, action);
          row.append(name, actions);
          list.append(row);
        }
        rows.delete(String(project.id));
        row.hidden = project.archived !== (filter === 'Archived');
        row.querySelector('.project-name').textContent = project.name;
        row.querySelector('[data-testid="project-summary"]').textContent =
          `${project.completedCount}/${project.totalCount} completed`;
        const action = row.querySelector('.project-actions button.secondary');
        action.textContent = project.archived ? 'Restore project' : 'Archive project';
        action.dataset.archived = String(project.archived);
      }
      for (const obsolete of rows.values()) obsolete.remove();
    }
    async function loadTasks(projectId, list, filter, archived = false) {
      const tasks = await fetch(`/api/projects/${projectId}/tasks`).then(response => response.json());
      const visibleTasks = tasks.filter(task => filter === 'All' || (filter === 'Open' ? !task.completed : task.completed));
      list.replaceChildren(...visibleTasks.map(task => {
        const row = element('div', undefined, { 'data-testid': 'task-row', class: 'task-row' });
        const checkbox = element('input', undefined, { type: 'checkbox', 'aria-label': `Complete ${task.title}` });
        checkbox.checked = task.completed;
        checkbox.disabled = archived;
        checkbox.addEventListener('change', async () => {
          await fetch(`/api/tasks/${task.id}`, {
            method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked })
          });
          await loadTasks(projectId, list, filter, archived);
        });
        row.append(checkbox, element('span', task.title));
        return row;
      }));
    }
    render();
  </script>
